using EasyData.Api.Models;using Microsoft.EntityFrameworkCore;namespace EasyData.Api.Data;public class AppDbContext(DbContextOptions<AppDbContext> options):DbContext(options){public DbSet<Diagnostico> Diagnosticos=>Set<Diagnostico>();public DbSet<Usuario> Usuarios=>Set<Usuario>();public DbSet<IngresoEquipo> IngresosEquipos=>Set<IngresoEquipo>();protected override void OnModelCreating(ModelBuilder b){b.Entity<Diagnostico>().HasIndex(x=>x.NumeroInforme).IsUnique();b.Entity<Usuario>().HasIndex(x=>x.NombreUsuario).IsUnique();b.Entity<IngresoEquipo>().HasIndex(x=>x.NumeroIngreso).IsUnique();}}